// Rayat Najd unified plant/tree product database.
//
// Batch 1 (pilot, 12 species): species already referenced elsewhere on the live
// site (servicesData.ts, NurseriesCatalog.tsx, PlantCareGuide.tsx, CatalogViewer.tsx).
// Batch 2 (25 species): remainder of "Native & Environmental Trees" (category 01)
// plus the start of "Fruit & Economic Trees" (category 02), per the full taxonomy
// brief.
//
// Data discipline: every agronomic fact below is backed by a cited source (Saudi
// official sources — National Center for Vegetation Cover Development & Combating
// Desertification (ncvc.gov.sa) — prioritized where a page existed; otherwise FAO-
// affiliated World Agroforestry/ICRAF, Kew-adjacent, or established horticultural
// extension/reference sources). Fields with no credible source found are left
// undefined and listed in `dataGaps` — never estimated.
//
// Images: left empty for every species below. The asset manifest's nursery/tree
// photo pools are categorized generically (e.g. "native drought-tolerant trees",
// "palm trees") and were never verified to the individual-species level, so no
// photo here can be honestly attached to a specific botanical identity yet. This
// is called out explicitly in each record's `dataGaps`.

