export function getPlantBySlug(slug: string): PlantProduct | undefined {
  return plantDatabase.find((p) => p.seo.slugEn === slug);
}

export function getPlantsByCategory(categoryId: string): PlantProduct[] {
  return plantDatabase.filter((p) => p.primaryCategory === categoryId);
}

export function getPlantsByTag(tag: string): PlantProduct[] {
  return plantDatabase.filter((p) => p.tags.includes(tag));
}
